ErrorStatuses = [...]storeErrorStatus{\n58 | \t{err: ErrNotFound, status: http.StatusNotFound},\n59 | \t{err: ErrConflict, status: http.StatusConflict},\n60 | \t{err: ErrInvalidID, status: http.StatusBadRequest},\n61 | \t{err: ErrUserAtCap, status: http.StatusTooManyRequests},\n62 | }\n63 | \n64 | // mapStoreError translates store errors for every HTTP handler that surfaces\n65 | // store failures, including session and admin handlers.\n66 | func mapStoreError(err error) int {\n67 | \tfor _, mapping := range storeErrorStatuses {\n68 | \t\tif errors.Is(err, mapping.err) {\n69 | \t\t\treturn mapping.status\n70 | \t\t}\n71 | \t}\n72 | \treturn http.StatusInternalServerError\n73 | }\n74 | \n75 | // writeStoreError gives session and admin handlers one response path while\n76 | // mapStoreError remains the sole store-error-to-status translation function.\n77 | func writeStoreError(w http.ResponseWriter, err error) {\n78 | \tstatus := mapStoreError(err)\n79 | \thttp.Error(w, err.Error(), status)\n80 | }\n81 | \n82 | // healthHandler reports how many sessions are currently held.\n83 | func healthHandler(store *Store) http.HandlerFunc {\n84 | \treturn func(w http.ResponseWriter, r *http.Request) {\n85 | \t\twriteJSON(w, map[string]int{\"sessions\": store.Len()})\n86 | \t}\n87 | }\n88 | \n89 | func writeJSON(w http.ResponseWriter, payload any) {\n90 | \tw.Header().Set(\"Content-Type\", \"application/json\")\n91 | \tif err := json.NewEncoder(w).Encode(payload); err != nil {\n92 | \t\tlog.Printf(\"write response: %v\", err)\n93 | \t}\n94 | }","runId":"run_20260904140944_c002df","schemaVersion":2,"status":"ok","truncated":false,"type":"tool_result"}
