{"args":{"content":"package main\n\nimport (\n\t\"net/http\"\n\t\"net/http/httptest\"\n\t\"testing\"\n\t\"time\"\n)\n\nfunc TestSessionLookupTable(t *testing.T) {\n\tfixedNow := time.Date(2025, time.January, 2, 3, 4, 5, 0, time.UTC)\n\tclock := func() time.Time { return fixedNow }\n\n\ttests := []struct {\n\t\tname   string\n\t\tmethod string\n\t\tpath   string\n\t\twant   int\n\t}{\n\t\t{name: \"live\", method: http.MethodGet, path: \"/session?id=live\", want: http.StatusOK},\n\t\t{name: \"missing\", method: http.MethodGet, path: \"/session?id=missing\", want: http.StatusNotFound},\n\t\t{name: \"wrong method\", method: http.MethodPut, path: \"/session?id=live\", want: http.StatusMethodNotAllowed},\n\t}\n\n\tfor _, tt := range tests {\n\t\tt.Run(tt.name, func(t *testing.T) {\n\t\t\tstore := newSessionStore(clock)\n\t\t\tstore.sessions[\"live\"] = session{\n\t\t\t\tID:        \"live\",\n\t\t\t\tExpiresAt: fixedNow.Add(time.Hour),\n\t\t\t}\n\n\t\t\tmux := http.NewServeMux()\n\t\t\tmux.HandleFunc(\"GET /session\", store.sessionHandler)\n\n\t\t\trecorder := httptest.NewRecorder()\n\t\t\trequest := httptest.NewRequest(tt.method, tt.path, nil)\n\t\t\tmux.ServeHTTP(recorder, request)\n\n\t\t\tif recorder.Code != tt.want {\n\t\t\t\tt.Fatalf(\"status code = %d; want %d\", recorder.Code, tt.want)\n\t\t\t}\n\t\t})\n\t}\n}\n","overwrite":true,"path":"lookup_table_test.go"},"id":"call_write_file_683433108cf37105","name":"write_file","runId":"run_20260904141707_c6c28d","schemaVersion":2,"sideEffect":"write","type":"tool_call"}
